command:
$ErrorActionPreference='Stop'
git fetch origin --prune
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$branch=(git branch --show-current).Trim()
if($branch -ne 'main'){throw "Expected main, found $branch"}
$paths=@(
'app/winui/MainWindow.xaml.cpp',
'app/winui/file_detail_controller.cpp',
'app/winui/file_list_state.h',
'app/winui/helper/FlyShellIsolationHelper.cpp',
'src/base/shell_assoc_type_core.cpp',
'src/base/shell_assoc_type_core.h',
'tests/winui/test_known_folder_artwork_contract.py'
)
$dirty=@(git status --porcelain)
Write-Output 'SYNC_STATUS_BEFORE'
$dirty | ForEach-Object { Write-Output $_ }
if($dirty.Count -eq 0){throw 'Expected redundant local Known Folder work before sync.'}
$dirtyPaths=@()
foreach($line in $dirty){
  if($line.Length -lt 4){continue}
  $p=$line.Substring(3).Trim()
  if($p.StartsWith('"') -and $p.EndsWith('"')){$p=$p.Substring(1,$p.Length-2)}
  $dirtyPaths += $p
}
foreach($p in $dirtyPaths){
  if($paths -notcontains $p){throw "Unexpected dirty path blocks sync: $p"}
}
foreach($p in $paths){
  if(-not (Test-Path -LiteralPath $p -PathType Leaf)){throw "Expected local file missing: $p"}
  $local=(git hash-object -- "$p").Trim()
  if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
  $remote=(git rev-parse "origin/main:$p").Trim()
  if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
  Write-Output "BLOB_COMPARE $p LOCAL=$local REMOTE=$remote"
  if($local -ne $remote){throw "Local file differs from accepted origin/main: $p"}
}
git stash push -u -m 'redundant-known-folder-work-already-on-main'
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$head=(git rev-parse HEAD).Trim()
$remoteHead=(git rev-parse origin/main).Trim()
if($head -ne $remoteHead){throw "HEAD mismatch after fast-forward: $head vs $remoteHead"}
$status=@(git status --porcelain)
if($status.Count -ne 0){$status|ForEach-Object{Write-Output $_};throw 'Checkout not clean after fast-forward.'}
$stash=(git stash list -1 --format='%gd %s').Trim()
Write-Output "STASH_BEFORE_DROP $stash"
if($stash -notmatch 'redundant-known-folder-work-already-on-main'){throw 'Expected safety stash missing.'}
git stash drop stash@{0}
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
Write-Output "SYNCED_HEAD $head"
Write-Output 'SYNC_STATUS_AFTER'
git status --short
